import { useState } from 'react';
import { Code, Group } from '@mantine/core';
import { MantineLogo } from '@mantine/logos';

const data = [
  { link: '/home', label: 'Home' },
  { link: '/about', label: 'About' },
  { link: '/photography', label: 'Photography' },
  { link: '/portfolio', label: 'Portfolio' },
];

export default function Home() {
  const [active, setActive] = useState('Home');

  const links = data.map((item) => (
    <Link
      to={item.link}
      className={`block p-2 text-white hover:bg-gray-700 ${item.label === active ? 'bg-gray-800' : ''}`}
      key={item.label}
      onClick={(event) => {
        event.preventDefault();
        setActive(item.label);
      }}
    >
      {item.label}
    </Link>
  ));

  return (
    <nav className="bg-gray-900 text-white">
      <div className="max-w-screen-lg mx-auto p-4">
        <Group className="flex justify-between items-center">
          <MantineLogo size={28} inverted />
          <Code fw={700} className="text-white">
            v3.1.2
          </Code>
        </Group>
        <div className="mt-4 space-y-2">
          {links}
        </div>
      </div>

      <div className="p-4">
        {/* Footer links (optional) */}
      </div>
    </nav>
  );
}
